package api

import (
	"database/sql"
	"encoding/json"
	"net/http"
	"testing"

	"github.com/luwa07832/config-center-api/internal/store"
)

func lineagePath(ns, env, version string) string {
	return "/namespaces/" + ns + "/environments/" + env + "/config-versions/" + version + "/lineage"
}

func postRollback(t *testing.T, handler http.Handler, ns, env, source string) {
	t.Helper()
	recorder := doRequest(t, handler, http.MethodPost,
		"/namespaces/"+ns+"/environments/"+env+"/config-versions/"+source+"/rollback", nil)
	if recorder.Code != http.StatusCreated {
		t.Fatalf("rollback status = %d body = %s", recorder.Code, recorder.Code, recorder.Body.String())
	}
}

func postPromote(t *testing.T, handler http.Handler, ns, env, source string) {
	t.Helper()
	recorder := doRequest(t, handler, http.MethodPost,
		"/namespaces/"+ns+"/environments/"+env+"/config-versions/"+source+"/promote", nil)
	if recorder.Code != http.StatusCreated {
		t.Fatalf("promote status = %d body = %s", recorder.Code, recorder.Body.String())
	}
}

type rawLineage struct {
	Namespace       string `json:"namespace"`
	Environment     string `json:"environment"`
	Version         VersionInfo
	Ancestors       []struct {
		VersionInfo
		Depth    int    `json:"depth"`
		Relation string `json:"relation"`
	} `json:"ancestors"`
	Descendants []struct {
		VersionInfo
		Depth         int   `json:"depth"`
		ParentVersion int64 `json:"parentVersion"`
	} `json:"descendants"`
	AncestorCount   int `json:"ancestorCount"`
	DescendantCount int `json:"descendantCount"`
}

func decodeLineage(t *testing.T, recorder *http.ResponseRecorder) rawLineage {
	t.Helper()
	var body rawLineage
	if err := json.Unmarshal(recorder.Body.Bytes(), &body); err != nil {
		t.Fatalf("decode %q: %v", recorder.Body.String(), err)
	}
	return body
}

func TestVersionLineageWalksRollbackAndPromotionEdges(t *testing.T) {
	_, handler := newTestRouter(t)
	publish(t, handler, "payments", "prod", "", map[string]any{"a": 1})
	publish(t, handler, "payments", "prod", "canary", map[string]any{"a": 2})
	postPromote(t, handler, "payments", "prod", "2")
	postRollback(t, handler, "payments", "prod", "3")
	publish(t, handler, "payments", "prod", "canary", map[string]any{"a": 5})
	postPromote(t, handler, "payments", "prod", "5")
	postRollback(t, handler, "payments", "prod", "6")
	// Scope: 1 full, 2 gray, 3 promotionOf 2, 4 rollbackOf 3 (gray),
	//        5 gray, 6 promotionOf 5, 7 rollbackOf 6 (full, effective).

	recorder := doRequest(t, handler, http.MethodGet, lineagePath("payments", "prod", "4"), nil)
	if recorder.Code != http.StatusOK {
		t.Fatalf("status = %d body = %s", recorder.Code, recorder.Body.String())
	}
	body := decodeLineage(t, recorder)
	if body.Namespace != "payments" || body.Environment != "prod" {
		t.Fatalf("scope = %s/%s", body.Namespace, body.Environment)
	}
	if body.Version.Version != 4 {
		t.Fatalf("root version = %d", body.Version.Version)
	}
	if body.Version.GrayTag == nil || *body.Version.GrayTag != "canary" {
		t.Fatalf("root grayTag = %v, want canary", body.Version.GrayTag)
	}
	if body.AncestorCount != 2 || len(body.Ancestors) != 2 {
		t.Fatalf("ancestorCount = %d len = %d", body.AncestorCount, len(body.Ancestors))
	}
	wantAncestors := []struct {
		version  int64
		depth    int
		relation string
	}{{3, 1, "rollback"}, {2, 2, "promotion"}}
	for i, want := range wantAncestors {
		got := body.Ancestors[i]
		if got.Version != want.version || got.Depth != want.depth || got.Relation != want.relation {
			t.Fatalf("ancestor[%d] = v%d depth=%d relation=%s", i, got.Version, got.Depth, got.Relation)
		}
		if got.Namespace != "payments" || got.Environment != "prod" {
			t.Fatalf("ancestor[%d] scope = %s/%s", i, got.Namespace, got.Environment)
		}
	}
	if body.DescendantCount != 1 || len(body.Descendants) != 1 {
		t.Fatalf("descendantCount = %d len = %d", body.DescendantCount, len(body.Descendants))
	}
	if body.Descendants[0].Version != 7 || body.Descendants[0].Depth != 1 ||
		body.Descendants[0].ParentVersion != 4 || body.Descendants[0].Relation != "" {
		d := body.Descendants[0]
		t.Fatalf("descendant = v%d depth=%d parent=%d relation=%q", d.Version, d.Depth, d.ParentVersion, d.Relation)
	}

	root := doRequest(t, handler, http.MethodGet, lineagePath("payments", "prod", "7"), nil)
	rootBody := decodeLineage(t, root)
	wantChain := []struct {
		version  int64
		relation string
	}{{6, "rollback"}, {5, "promotion"}, {4, "rollback"}, {3, "rollback"}, {2, "promotion"}}
	if rootBody.AncestorCount != len(wantChain) {
		t.Fatalf("ancestorCount = %d, want %d", rootBody.AncestorCount, len(wantChain))
	}
	for i, want := range wantChain {
		got := rootBody.Ancestors[i]
		if got.Version != want.version || got.Depth != i+1 || got.Relation != want.relation {
			t.Fatalf("ancestor[%d] = v%d depth=%d relation=%s", i, got.Version, got.Depth, got.Relation)
		}
	}
	if rootBody.Version.Effective != true {
		t.Fatalf("v7 must be effective")
	}
	if rootBody.DescendantCount != 0 || len(rootBody.Descendants) != 0 {
		t.Fatalf("descendants = %v, want empty", rootBody.Descendants)
	}
}

func TestVersionLineageReachableFromGrayVersionThroughPromotions(t *testing.T) {
	_, handler := newTestRouter(t)
	publish(t, handler, "payments", "prod", "", map[string]any{"a": 1})
	publish(t, handler, "payments", "prod", "canary", map[string]any{"a": 2})
	postPromote(t, handler, "payments", "prod", "2")
	publish(t, handler, "payments", "prod", "canary", map[string]any{"a": 3})
	postPromote(t, handler, "payments", "prod", "4")
	postRollback(t, handler, "payments", "prod", "3")
	// 1 full, 2 gray, 3 promo 2, 4 gray, 5 promo 4, 6 rollback 3.

