		if rollback != 0 {
			v.RollbackOf = sql.NullInt64{Int64: rollback, Valid: true}
		}
		if promotion != 0 {
			v.PromotionOf = sql.NullInt64{Int64: promotion, Valid: true}
		}
		return v
	}
	// v3 records both fields; the ancestor walk must follow rollbackOf (v2), never promotionOf (v1).
